def best_circular_selection(values, k):
    n = len(values)
    if n == 0:
        raise ValueError("values must be non-empty")
    if k < 0 or k > n:
        raise ValueError("k out of range")
    if k == 0:
        return 0

    # Feasibility on a circle: a single element is not adjacent to itself,
    # otherwise at most floor(n / 2) elements can be chosen.
    if n == 1:
        if k == 1:
            return values[0]
        raise ValueError("no valid selection of exactly k elements")
    if k > n // 2:
        raise ValueError("no valid selection of exactly k elements")

    NEG = float("-inf")

    def linear(arr, m):
        """Max sum of exactly m pairwise non-adjacent elements of a linear array.
        Returns NEG if infeasible."""
        if m == 0:
            return 0
        L = len(arr)
        if m > (L + 1) // 2:
            return NEG
        # dp[i][j] = best sum choosing exactly j from the first i elements
        # dp[i][j] = max(dp[i-1][j], dp[i-2][j-1] + arr[i-1])
        prev2 = [0] + [NEG] * m   # dp[i-2] (dp[-1] behaves like dp[0])
        prev1 = [0] + [NEG] * m   # dp[i-1]
        for i in range(1, L + 1):
            v = arr[i - 1]
            cur = [0] + [NEG] * m
            top = min(m, (i + 1) // 2)
            for j in range(1, top + 1):
                a = prev1[j]
                b = prev2[j - 1] + v
                cur[j] = a if a > b else b
            prev2 = prev1
            prev1 = cur
        return prev1[m]

    # Case 1: index 0 is not chosen -> linear problem on values[1:].
    best = linear(values[1:], k)

    # Case 2: index 0 is chosen -> indices 1 and n-1 are excluded,
    # linear problem on values[2:n-1] with k-1 picks.
    rest = linear(values[2:n - 1], k - 1)
    if rest != NEG:
        cand = values[0] + rest
        if cand > best:
            best = cand

    if best == NEG:
        raise ValueError("no valid selection of exactly k elements")
    return int(best)

from collections import deque


def min_steps(grid, c):
    R = len(grid)
    C = len(grid[0])
    if grid[0][0] == -1 or grid[R - 1][C - 1] == -1:
        return -1

    INF = float("inf")
    N = R * C
    flat = [v for row in grid for v in row]

    def bfs(src):
        dist = [INF] * N
        dist[src] = 0
        dq = deque([src])
        while dq:
            u = dq.popleft()
            d = dist[u] + 1
            r, col = divmod(u, C)
            if r > 0:
                v = u - C
                if flat[v] != -1 and dist[v] == INF:
                    dist[v] = d
                    dq.append(v)
            if r < R - 1:
                v = u + C
                if flat[v] != -1 and dist[v] == INF:
                    dist[v] = d
                    dq.append(v)
            if col > 0:
                v = u - 1
                if flat[v] != -1 and dist[v] == INF:
                    dist[v] = d
                    dq.append(v)
            if col < C - 1:
                v = u + 1
                if flat[v] != -1 and dist[v] == INF:
                    dist[v] = d
                    dq.append(v)
        return dist

    ds = bfs(0)        # walking distance from the start
    de = bfs(N - 1)    # walking distance to the end

    best = ds[N - 1]   # pure walking (INF if impossible)

    # For each label: the cheapest cell to teleport from (by ds)
    # and the cheapest cell to teleport to (by de).
    #
    # The "must jump to a different cell" rule needs no special handling:
    # if the best source and best target were the same cell u, the candidate
    # ds[u] + c + de[u] is >= the plain walking distance, which is already
    # a valid answer, so it can never produce a wrong (too small) result.
    min_s = {}
    min_e = {}
    for i in range(N):
        lab = flat[i]
        if lab == -1:
            continue
        a = ds[i]
        if a < min_s.get(lab, INF):
            min_s[lab] = a
        b = de[i]
        if b < min_e.get(lab, INF):
            min_e[lab] = b

    for lab, a in min_s.items():
        b = min_e.get(lab, INF)
        if a != INF and b != INF:
            cand = a + c + b
            if cand < best:
                best = cand

    return best if best != INF else -1

def max_sessions(intervals, gap):
    """Return the maximum number of sessions that can be held in one room,
    with at least `gap` idle time between consecutive selected sessions."""
    if not intervals:
        return 0

    count = 0
    next_allowed = None  # earliest time the next session may start

    # Take sessions in order of earliest end time.
    for start, end in sorted(intervals, key=lambda iv: iv[1]):
        if next_allowed is None or start >= next_allowed:
            count += 1
            next_allowed = end + gap

    return count

def smallest_balanced(s):
    n = len(s)
    if n % 2:
        raise ValueError("odd length string cannot be balanced")

    # A balanced string has exactly n/2 '(' characters.
    need_open = n // 2 - s.count('(')
    if need_open < 0 or need_open > s.count('?'):
        raise ValueError("no balanced replacement exists")

    out = []
    bal = 0
    for ch in s:
        if ch == '?':
            if need_open > 0:
                ch = '('
                need_open -= 1
            else:
                ch = ')'
        if ch == '(':
            bal += 1
        elif ch == ')':
            bal -= 1
            if bal < 0:
                raise ValueError("no balanced replacement exists")
        else:
            raise ValueError("invalid character in input")
        out.append(ch)

    # bal is necessarily 0 here: exactly n/2 '(' and n/2 ')'.
    return ''.join(out)

def longest_spaced_repeat(s, gap):
    n = len(s)
    best = 0
    # d = q - p is the distance between the two starting positions.
    # For a fixed d, a run of k consecutive matches s[i] == s[i+d] gives a
    # repeated substring of length k, of which at most d - gap can be used
    # (so that q >= p + L + gap).
    for d in range(n - 1, gap, -1):
        cap = d - gap
        if cap <= best:
            break  # smaller d only gives smaller caps
        run = 0
        for i in range(n - d):
            if s[i] == s[i + d]:
                run += 1
                if run > best:
                    best = min(run, cap)
                    if best == cap:
                        break  # can't do better on this diagonal
            else:
                run = 0
    return best

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set())
        for d in ds:
            graph.setdefault(d, set())
            graph[pkg].add(d)          # set => duplicate entries collapse

    order = []
    done = set()        # fully processed, already in `order`
    visiting = set()    # nodes on the current DFS path only

    for root in sorted(graph):
        if root in done:
            continue
        visiting.add(root)
        stack = [(root, iter(sorted(graph[root])))]
        while stack:
            node, it = stack[-1]
            for dep in it:
                if dep in done:
                    continue           # shared dependency, already built
                if dep in visiting:
                    raise ValueError("dependency cycle detected at " + dep)
                visiting.add(dep)
                stack.append((dep, iter(sorted(graph[dep]))))
                break
            else:
                # all dependencies finished
                stack.pop()
                visiting.discard(node)
                done.add(node)
                order.append(node)
    return order

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        cur = ordered[i]
        # Same start is always a conflict (even for two pure insertions);
        # otherwise conflict if cur starts inside prev's delete range.
        if cur[0] == prev[0] or cur[0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or delete < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")

    # Build the output from the ORIGINAL document, so no hunk can shift
    # the coordinates of another.
    result = []
    pos = 0
    for start, delete, insert in ordered:
        result.extend(lines[pos:start])   # untouched lines before this hunk
        result.extend(insert)             # replacement lines
        pos = start + delete              # skip the deleted lines
    result.extend(lines[pos:])            # untouched tail
    return result

import copy


def merge_settings(defaults, overrides):
    result = {}

    # Keys from defaults (keeps their original order).
    for key, default_value in defaults.items():
        if key in overrides:
            override_value = overrides[key]
            if isinstance(default_value, dict) and isinstance(override_value, dict):
                result[key] = merge_settings(default_value, override_value)
            else:
                # Override replaces the default, even when falsy
                # (False, 0, "", [], {}, None).
                result[key] = copy.deepcopy(override_value)
        else:
            result[key] = copy.deepcopy(default_value)

    # Keys present only in overrides are added, even when falsy.
    for key, override_value in overrides.items():
        if key not in defaults:
            result[key] = copy.deepcopy(override_value)

    return result

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        # Drop admitted calls that have expired (expired when timestamp - t >= window).
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        # Admit only if strictly fewer than max_calls admitted calls remain in the window.
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

import heapq


class CountingBag:
    """A multiset of hashable items with deterministic most-common ordering.

    Items are ranked by count (descending); ties are broken by entry moment
    (earlier first), where an item's entry moment is the most recent time it
    went from absent to present.
    """

    def __init__(self):
        # item -> count (always >= 1).
        # Dict insertion order doubles as entry order: updating an existing
        # key keeps its position, while deleting a key and re-inserting it
        # places it at the end, which matches the "re-enters as brand new" rule.
        self._counts = {}
        self._total = 0

    def add(self, item) -> int:
        """Add one occurrence of item; return its new count."""
        new_count = self._counts.get(item, 0) + 1
        self._counts[item] = new_count
        self._total += 1
        return new_count

    def discard(self, item) -> bool:
        """Remove one occurrence of item; return True if one was removed."""
        current = self._counts.get(item)
        if current is None:
            return False
        if current == 1:
            del self._counts[item]  # leaves the bag; entry moment forgotten
        else:
            self._counts[item] = current - 1
        self._total -= 1
        return True

    def count(self, item) -> int:
        """Current count of item (0 if absent)."""
        return self._counts.get(item, 0)

    def __len__(self) -> int:
        """Total number of occurrences across all items."""
        return self._total

    def distinct(self) -> int:
        """Number of distinct items currently present."""
        return len(self._counts)

    def most_common(self, k) -> list:
        """The k highest-count items as (item, count) tuples.

        Ordered by count descending, ties broken by earlier entry moment.
        """
        if k < 0:
            raise ValueError("k must be non-negative")
        if k == 0 or not self._counts:
            return []

        if k >= len(self._counts):
            # sorted() is stable, so equal counts stay in entry order.
            return sorted(self._counts.items(), key=lambda kv: -kv[1])

        # Top-k via heap: O(n log k). The entry index is unique, so the
        # tuple comparison never falls through to comparing items themselves
        # (which might not be orderable).
        decorated = (
            (-cnt, idx, item)
            for idx, (item, cnt) in enumerate(self._counts.items())
        )
        return [(item, -neg) for neg, _, item in heapq.nsmallest(k, decorated)]

    def __contains__(self, item) -> bool:
        return item in self._counts

    def __repr__(self) -> str:
        return f"CountingBag({self._counts!r})"

from bisect import bisect_left, insort


class Leaderboard:
    """Leaderboard where each player's ranking score is their best-ever score."""

    def __init__(self):
        # player -> (best, seq), where seq is the order of the improving submission
        self._info = {}
        # Sorted list of (-best, seq, player): best descending, then earliest first.
        # seq is unique, so comparisons never reach the player element.
        self._order = []
        self._seq = 0

    def submit(self, player, score):
        current = self._info.get(player)
        if current is not None:
            old_best, old_seq = current
            if score <= old_best:
                return False  # no improvement: change nothing
            # Remove the player's old entry. (-old_best, old_seq) sorts just
            # before (-old_best, old_seq, player), so bisect_left lands on it.
            idx = bisect_left(self._order, (-old_best, old_seq))
            del self._order[idx]

        seq = self._seq
        self._seq += 1
        self._info[player] = (score, seq)
        insort(self._order, (-score, seq, player))
        return True

    def best(self, player):
        return self._info[player][0]  # KeyError for unknown players

    def rank(self, player):
        best = self._info[player][0]  # KeyError for unknown players
        # (-best,) sorts before every entry with that best and after every
        # strictly greater best, so the index is the count of better players.
        return bisect_left(self._order, (-best,)) + 1

    def top(self, k):
        if k < 0:
            raise ValueError("k must be non-negative")
        return [(player, -neg_best) for neg_best, _, player in self._order[:k]]

    def player_count(self):
        return len(self._info)

class UndoStack:
    """A LIFO stack whose push/pop operations can be undone."""

    _PUSH = 0
    _POP = 1

    def __init__(self):
        self._items = []
        # Each history entry is a tuple: (_PUSH,) or (_POP, value)
        self._history = []

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append((self._PUSH,))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty UndoStack")
        value = self._items.pop()
        self._history.append((self._POP, value))
        return value

    def peek(self):
        if not self._items:
            raise IndexError("peek from empty UndoStack")
        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        entry = self._history.pop()
        if entry[0] == self._PUSH:
            # Reverse a push: remove the value it added (it must be on top,
            # since all later operations have already been undone).
            self._items.pop()
        else:
            # Reverse a pop: put the exact popped object back on top.
            self._items.append(entry[1])

    def __len__(self) -> int:
        return len(self._items)

class VersionedKV:
    """Key-value store with commit snapshots, point-in-time reads and rollback.

    The working state is a plain dict. Committed snapshots are kept in an
    append-only list, where snapshot ``v`` is stored at index ``v - 1``.

    Snapshots are taken lazily (copy-on-write): ``commit()`` and
    ``rollback()`` share the dict between the working state and the history,
    and the working state is only copied when it is next mutated. This makes
    commits and rollbacks O(1), and a commit with no changes costs no extra
    memory.
    """

    def __init__(self):
        self._working = {}
        self._snapshots = []      # _snapshots[v - 1] is the snapshot for version v
        self._shared = False      # True if _working is also referenced by history

    # ------------------------------------------------------------------ #
    # internals
    # ------------------------------------------------------------------ #

    def _own_working(self):
        """Ensure the working dict is private before mutating it."""
        if self._shared:
            self._working = dict(self._working)
            self._shared = False

    def _check_version(self, version, lowest):
        if (
            not isinstance(version, int)
            or isinstance(version, bool)
            or not (lowest <= version <= len(self._snapshots))
        ):
            raise ValueError(
                f"invalid version {version!r}: expected an integer in "
                f"[{lowest}, {len(self._snapshots)}]"
            )

    # ------------------------------------------------------------------ #
    # working state
    # ------------------------------------------------------------------ #

    def set(self, key, value) -> None:
        hash(key)  # reject unhashable keys before doing any copying
        self._own_working()
        self._working[key] = value

    def delete(self, key) -> None:
        if key not in self._working:
            raise KeyError(key)
        self._own_working()
        del self._working[key]

    def get(self, key):
        return self._working[key]  # raises KeyError if absent

    def has(self, key) -> bool:
        return key in self._working

    # ------------------------------------------------------------------ #
    # history
    # ------------------------------------------------------------------ #

    def commit(self) -> int:
        self._snapshots.append(self._working)
        self._shared = True       # next mutation must copy first
        return len(self._snapshots)

    def get_at(self, key, version):
        self._check_version(version, lowest=1)
        return self._snapshots[version - 1][key]  # raises KeyError if absent

    def rollback(self, version) -> None:
        self._check_version(version, lowest=0)
        if version == 0:
            self._working = {}
            self._shared = False
        else:
            self._working = self._snapshots[version - 1]
            self._shared = True   # copy-on-write protects the snapshot

    def latest(self) -> int:
        return len(self._snapshots)

def rank_scores(scores: list) -> list[int]:
    """Assign competition ("1224") ranks to scores; higher is better, rank 1 is best."""
    # Reject NaN up front (NaN is the only value not equal to itself).
    for s in scores:
        if s != s:
            raise ValueError("scores must not contain NaN")

    # Sort a copy in descending order; the input list is not mutated.
    ordered = sorted(scores, reverse=True)

    # The first position at which a value appears in descending order is
    # 1 + (number of scores strictly greater than it).
    rank_of = {}
    for i, s in enumerate(ordered):
        if s not in rank_of:
            rank_of[s] = i + 1

    return [rank_of[s] for s in scores]

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    result = {}
    for i, row in enumerate(rows):
        # a. shape
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(
                f"row {i}: expected a tuple of exactly 3 elements "
                f"(category, amount, refunded)"
            )

        category, amount, refunded = row

        # b. category
        if not isinstance(category, str) or category == "":
            raise ValueError(f"row {i}: category must be a non-empty str")

        # c. amount type (bool is explicitly rejected)
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(f"row {i}: amount must be an int or float (not bool)")

        # d. amount range (written as `not >= 0` so NaN is rejected too)
        if not (amount >= 0):
            raise ValueError(f"row {i}: amount must be >= 0")

        # e. refunded
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i}: refunded must be a bool")

        value = float(amount)

        summary = result.get(category)
        if summary is None:
            summary = {"count": 0, "gross": 0.0, "net": 0.0, "largest": value}
            result[category] = summary

        summary["count"] += 1
        summary["gross"] += value
        if not refunded:
            summary["net"] += value
        if value > summary["largest"]:
            summary["largest"] = value

    return result

def clamp_values(values, low, high):
    """Return a new list with every number in `values` clamped to [low, high]."""
    if not isinstance(values, list):
        raise TypeError("values must be a list")

    for bound in (low, high):
        if isinstance(bound, bool) or not isinstance(bound, (int, float)):
            raise TypeError("bounds must be numbers")

    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, item in enumerate(values):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError(f"element at index {i} must be a number")
        if item < low:
            result.append(low)
        elif item > high:
            result.append(high)
        else:
            result.append(item)
    return result

def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    name_chars = (
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789_"
    )

    out = []
    n = len(template)
    i = 0

    while i < n:
        c = template[i]

        if c == "{":
            # Escape "{{" always wins.
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue

            # Placeholder opening at position i.
            start = i
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError(
                        "unclosed placeholder at position " + str(start)
                    )
                ch = template[j]
                if ch == "}":
                    break
                if ch not in name_chars:
                    raise ValueError(
                        "invalid placeholder at position " + str(start)
                    )
                j += 1

            if j == start + 1:
                raise ValueError("empty placeholder at position " + str(start))

            name = template[start + 1:j]
            if name not in context:
                raise KeyError(name)
            out.append(str(context[name]))
            i = j + 1

        elif c == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
            else:
                raise ValueError("stray '}' at position " + str(i))

        else:
            out.append(c)
            i += 1

    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")

    DIGITS = "0123456789"

    def parse_digits(s):
        # Split-and-combine parsing so very long literals stay exact and do
        # not hit CPython's int<->str digit-count limit on int().
        n = len(s)
        if n <= 512:
            return int(s)
        mid = n // 2
        return parse_digits(s[:mid]) * (10 ** (n - mid)) + parse_digits(s[mid:])

    stack = []
    for i, tok in enumerate(tokens):
        if not isinstance(tok, str):
            raise TypeError(
                "token %d must be a str, got %s" % (i, type(tok).__name__)
            )

        if tok == "+" or tok == "-" or tok == "*" or tok == "/":
            if len(stack) < 2:
                raise ValueError("stack underflow at token %d" % i)
            right = stack.pop()
            left = stack.pop()
            if tok == "+":
                result = left + right
            elif tok == "-":
                result = left - right
            elif tok == "*":
                result = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero at token %d" % i)
                # Truncate toward zero using exact integer arithmetic only.
                q = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    q = -q
                result = q
            stack.append(result)
            continue

        # Operand: optional single sign, then one or more ASCII digits.
        negative = False
        body = tok
        if body[:1] == "+" or body[:1] == "-":
            negative = body[0] == "-"
            body = body[1:]

        valid = len(body) > 0
        if valid:
            for ch in body:
                if ch not in DIGITS:
                    valid = False
                    break
        if not valid:
            raise ValueError("unknown token: token %d (%r)" % (i, tok))

        value = parse_digits(body)
        stack.append(-value if negative else value)

    if len(stack) > 1:
        raise ValueError(
            "leftover operands: %d values remain on the stack" % len(stack)
        )
    return stack[0]

class _RawKey(str):
    """A str whose repr() is its raw text.

    str(KeyError(x)) is repr(x), which would escape quotes, backslashes or
    newlines in a segment. Wrapping the segment in this class guarantees that
    str(exc) contains the segment verbatim, while the exception is still a
    plain KeyError and exc.args[0] == segment.
    """

    __slots__ = ()

    def __repr__(self):
        return str.__str__(self)


def _step(node, segment):
    """Descend exactly one level from `node` using `segment`."""
    if isinstance(node, dict):
        if segment not in node:
            raise KeyError(_RawKey(segment))
        return node[segment]

    if isinstance(node, list):
        negative = segment.startswith("-")
        digits = segment[1:] if negative else segment
        # one or more ASCII digits only (rejects "", "+3", "--1", "²", etc.)
        if not (digits.isascii() and digits.isdigit()):
            raise ValueError(
                "invalid index %r: expected an integer literal" % (segment,)
            )
        significant = digits.lstrip("0")
        # More than 19 significant digits cannot index any real list; reject
        # early so int() never hits its huge-string conversion limit.
        if len(significant) > 19:
            raise IndexError("list index out of range: " + segment)
        index = int(significant or "0")
        if negative:
            index = -index
        size = len(node)
        if not (-size <= index < size):
            raise IndexError("list index out of range: " + segment)
        return node[index]

    raise TypeError(
        "cannot descend into %s with segment %r"
        % (type(node).__name__, segment)
    )


def _descend(node, segments, start, stop):
    """Consume segments[start:stop] (non-empty range), left to right.

    Recursion splits the range in half, so the call depth is O(log n) rather
    than O(n); very long paths cannot hit the interpreter's recursion limit.
    The left half is always fully resolved before the right half, so errors
    surface in path order.
    """
    if stop - start == 1:
        return _step(node, segments[start])
    mid = (start + stop) // 2
    return _descend(_descend(node, segments, start, mid), segments, mid, stop)


def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string, got %s" % type(path).__name__)
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")
    if "" in segments:  # leading dot, trailing dot, or ".."
        raise ValueError("empty segment in path %r" % (path,))

    return _descend(data, segments, 0, len(segments))

def top_k_frequent(items, k):
    """Return (value, count) pairs for the k most frequent distinct values.

    Pairs are ordered by count descending; ties are broken by first
    occurrence in `items`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")

    # Count occurrences; dict insertion order records first occurrence.
    counts = {}
    for value in items:
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1

    if k == 0 or not counts:
        return []

    # Group values by count. Each bucket keeps first-occurrence order
    # because we walk `counts` in insertion order.
    buckets = {}
    highest = 0
    for value, count in counts.items():
        if count in buckets:
            buckets[count].append(value)
        else:
            buckets[count] = [value]
        if count > highest:
            highest = count

    # Walk counts from highest to lowest, collecting up to k pairs.
    result = []
    count = highest
    while count >= 1 and len(result) < k:
        bucket = buckets.get(count)
        if bucket is not None:
            for value in bucket:
                result.append((value, count))
                if len(result) == k:
                    break
        count -= 1

    return result
